create or replace function private.schoolpro_validate_calendar() returns trigger language plpgsql set search_path='' as $$begin if new.term_start_date is not null and new.term_end_date is not null then if new.term_end_date<new.term_start_date then raise exception 'Term ending must follow its beginning';end if;perform pg_advisory_xact_lock(hashtextextended(new.school_id::text,0));if exists(select 1 from public.schoolpro_result_term_settings t where t.school_id=new.school_id and (t.session,t.term) is distinct from(new.session,new.term) and t.id<>new.id and t.term_start_date<=new.term_end_date and t.term_end_date>=new.term_start_date) then raise exception 'Academic term dates cannot overlap in the same school';end if;end if;return new;end$$;
